
(function(){
  'use strict';
  var A={title:"",flower:"",bg:"",art:"",tree:""};
  var BTN={play:"",set:"",rec:"",help:""};
  var RM=false;try{RM=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)}catch(e){}
  var st=null,running=false,lastDraw=0;
  function rnd(a,b){return a+Math.random()*(b-a)}
  function mkStars(w,h){
    var n=Math.max(32,Math.min(72,Math.round(w*h/9500))),arr=[],i;
    for(i=0;i<n;i++)arr.push({x:Math.random(),y:Math.pow(Math.random(),1.25),s:Math.random(),ph:rnd(0,90),sp:Math.random(),k:Math.random(),ax:rnd(0,6.28),ay:rnd(0,6.28)});
    return arr;
  }
  function size(){
    if(!st)return;var w=st.box.clientWidth,h=st.box.clientHeight,d=Math.min(window.devicePixelRatio||1,2);
    if(!w||!h)return;st.w=w;st.h=h;st.dpr=d;st.cv.width=Math.round(w*d);st.cv.height=Math.round(h*d);
    if(!st.stars)st.stars=mkStars(w,h);
    if(RM)draw(0);
  }
  function attach(){
    var scr=document.querySelector('.screen--splash');if(!scr)return;
    if(st&&st.scr===scr&&scr.contains(st.box))return;
    try{
      var L=document.createElement('div');L.className='sv-layers';L.setAttribute('aria-hidden','true');
      L.innerHTML='<img class="sv-bg" alt="" draggable="false"><div class="sv-glow"></div><canvas class="sv-sparks"></canvas><div class="sv-artw"><img class="sv-art" alt="" draggable="false"></div><img class="sv-tree" alt="" draggable="false"><img class="sv-title" alt="Севастополис" draggable="false"><img class="sv-flower" alt="" draggable="false">';
      L.querySelector('.sv-bg').src='data:image/webp;base64,'+A.bg;
      L.querySelector('.sv-art').src='data:image/webp;base64,'+A.art;
      L.querySelector('.sv-tree').src='data:image/webp;base64,'+A.tree;
      L.querySelector('.sv-title').src='data:image/webp;base64,'+A.title;
      L.querySelector('.sv-flower').src='data:image/webp;base64,'+A.flower;
      scr.insertBefore(L,scr.firstChild);
      ['play','set','rec','help'].forEach(function(k){scr.style.setProperty('--sv-'+k,'url("data:image/webp;base64,'+BTN[k]+'")')});
      var cv=L.querySelector('.sv-sparks');
      st={scr:scr,box:L,cv:cv,ctx:cv.getContext('2d'),w:0,h:0,dpr:1,stars:null};
      size();
      if(window.ResizeObserver){new ResizeObserver(size).observe(L)}else{window.addEventListener('resize',size)}
      if(!running){running=true;requestAnimationFrame(loop)}
    }catch(e){window.__sv131Err=e.stack||String(e)}
  }
  function rgb(k,a){return 'rgba('+((255-50*k)|0)+','+((237+8*k)|0)+','+((158+97*k)|0)+','+a+')'}
  function draw(t){
    if(!st||!st.w)return;
    var c=st.ctx,d=st.dpr,W=st.w*d,H=st.h*d,u=Math.max(.6,st.h/700)*d,i,p,tw,a,x,y,R,Ls,lw,g;
    c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,st.cv.width,st.cv.height);c.globalCompositeOperation='lighter';
    for(i=0;i<st.stars.length;i++){
      p=st.stars[i];
      a=RM?.5:Math.pow(.5+.5*Math.sin(t*(1.1+p.sp*1.5)+p.ph),3)*.95;
      if(a<.02)continue;
      x=p.x*W+(RM?0:Math.sin(t*.45+p.ax)*3*u);y=p.y*H+(RM?0:Math.cos(t*.4+p.ay)*3*u);
      R=(4+9*p.s)*u;
      g=c.createRadialGradient(x,y,0,x,y,R*2.2);g.addColorStop(0,rgb(p.k,a));g.addColorStop(.25,rgb(p.k,a*.45));g.addColorStop(1,rgb(p.k,0));
      c.fillStyle=g;c.beginPath();c.arc(x,y,R*2.2,0,6.2832);c.fill();
      Ls=R*3.4;lw=Math.max(1,u*1.1);
      g=c.createLinearGradient(x-Ls,y,x+Ls,y);g.addColorStop(0,rgb(p.k,0));g.addColorStop(.5,rgb(p.k,a*.85));g.addColorStop(1,rgb(p.k,0));c.fillStyle=g;c.fillRect(x-Ls,y-lw/2,2*Ls,lw);
      g=c.createLinearGradient(x,y-Ls,x,y+Ls);g.addColorStop(0,rgb(p.k,0));g.addColorStop(.5,rgb(p.k,a*.85));g.addColorStop(1,rgb(p.k,0));c.fillStyle=g;c.fillRect(x-lw/2,y-Ls,lw,2*Ls);
    }
    c.globalCompositeOperation='source-over';
  }
  function loop(now){
    var on=st&&st.scr&&st.scr.classList.contains('on');
    if(RM||document.hidden||!on){setTimeout(function(){requestAnimationFrame(loop)},300);return}
    if(now-lastDraw>33){lastDraw=now;try{draw(now/1000)}catch(e){window.__sv131Err=e.stack||String(e)}}
    requestAnimationFrame(loop);
  }
  attach();setInterval(attach,700);
})();
